input.content:
/* ==========================================================================
   Relay — operations console
   Palette: one cool accent (#6fa8ff) over desaturated blue-grey neutrals.
   ========================================================================== */

:root {
  --bg: #0b0e12;
  --bg-2: #0e1319;
  --panel: #12171e;
  --panel-2: #161c24;
  --panel-3: #1b222c;
  --line: #232b36;
  --line-2: #1a212a;
  --line-strong: #33404f;

  --text: #e7ecf3;
  --text-2: #a1acbc;
  --text-3: #76828f;

  --accent: #6fa8ff;
  --accent-soft: rgba(111, 168, 255, 0.08);
  --accent-line: rgba(111, 168, 255, 0.4);

  --good: #4ecb92;
  --warn: #e5b64c;
  --bad: #f27066;
  --crit: #ff6b62;
  --high: #f7a45a;
  --medium: #e3c65a;
  --low: #93a0b2;

  --rail-w: 68px;
  --topbar-h: 52px;
  --radius: 4px;

  --font: ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas,
    "Liberation Mono", monospace;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 400 13px/1.45 var(--font);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

button {
  -webkit-tap-highlight-color: transparent;
}

a {
  color: inherit;
  text-decoration: none;
}

h1,
h2,
h3,
p,
dl,
dd,
figure {
  margin: 0;
}

ul,
ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

svg {
  display: block;
}

[hidden] {
  display: none !important;
}

::selection {
  background: rgba(111, 168, 255, 0.28);
  color: #fff;
}

:where(a, button, input, select, [tabindex]):focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

:where(input, select):focus-visible {
  outline-offset: 1px;
}

.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: fixed;
  top: 8px;
  left: 78px;
  z-index: 100;
  padding: 8px 12px;
  background: var(--accent);
  color: #07101f;
  font-weight: 600;
  font-size: 12px;
  border-radius: 3px;
  transform: translateY(-160%);
  transition: transform 0.15s ease;
}

.skip-link:focus {
  transform: translateY(0);
  outline-offset: 2px;
}

/* --------------------------------------------------------------------------
   Shell
   -------------------------------------------------------------------------- */

.app {
  display: grid;
  grid-template-columns: var(--rail-w) minmax(0, 1fr);
  min-height: 100vh;
}

.workspace {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

/* --------------------------------------------------------------------------
   Navigation rail
   -------------------------------------------------------------------------- */

.rail {
  position: sticky;
  top: 0;
  z-index: 40;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100vh;
  padding: 12px 0;
  background: #0a0d11;
  border-right: 1px solid var(--line);
}

.rail__brand {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  margin-bottom: 14px;
  color: var(--accent);
  background: var(--panel-2);
  border: 1px solid var(--line);
  border-radius: 5px;
  transition: border-color 0.15s ease, color 0.15s ease;
}

.rail__brand:hover {
  border-color: var(--line-strong);
  color: #9cc4ff;
}

.rail__nav {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  width: 100%;
}

.rail__nav li {
  width: 100%;
}

.rail__item {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  width: 56px;
  height: 50px;
  margin: 0 auto;
  padding: 0;
  color: var(--text-3);
  background: transparent;
  border: 0;
  border-radius: 4px;
  font-size: 9.5px;
  letter-spacing: 0.02em;
  cursor: pointer;
  transition: color 0.15s ease, background-color 0.15s ease;
}

.rail__item span:not(.rail__badge) {
  line-height: 1;
}

.rail__item:hover {
  color: var(--text-2);
  background: var(--panel-2);
}

.rail__item[aria-current="page"] {
  color: var(--text);
  background: var(--panel-2);
}

.rail__item[aria-current="page"]::before {
  content: "";
  position: absolute;
  left: 0;
  top: 12px;
  bottom: 12px;
  width: 2px;
  border-radius: 1px;
  background: var(--accent);
}

.rail__item[aria-current="page"] svg {
  color: var(--accent);
}

.rail__badge {
  position: absolute;
  top: 6px;
  right: 8px;
  min-width: 14px;
  padding: 1px 3px;
  background: var(--panel-3);
  border: 1px solid var(--line);
  border-radius: 7px;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 8.5px;
  line-height: 1.2;
  text-align: center;
}

.rail__foot {
  margin-top: auto;
  padding-top: 10px;
  border-top: 1px solid var(--line-2);
  width: 100%;
}

/* --------------------------------------------------------------------------
   Top status bar
   -------------------------------------------------------------------------- */

.topbar {
  position: sticky;
  top: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  height: var(--topbar-h);
  padding: 0 20px;
  background: var(--bg);
  border-bottom: 1px solid var(--line);
}

.topbar__left,
.topbar__right {
  display: flex;
  align-items: center;
  min-width: 0;
}

.topbar__left {
  gap: 12px;
}

.topbar__right {
  gap: 13px;
}

.wordmark {
  display: none;
  font-size: 15px;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.context {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  font-size: 11.5px;
  color: var(--text-2);
}

.context__env {
  padding: 2px 6px;
  color: #c9d5e4;
  background: var(--panel-2);
  border: 1px solid var(--line);
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.context__sep {
  color: var(--text-3);
}

.context__path {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-2);
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 23px;
  padding: 0 8px;
  border-radius: 3px;
  font-size: 11px;
  font-weight: 500;
  white-space: nowrap;
}

.status-pill--warn {
  color: #ecc978;
  background: rgba(229, 182, 76, 0.08);
  border: 1px solid rgba(229, 182, 76, 0.26);
}

.status-pill__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--warn);
}

.status-pill__detail {
  color: rgba(236, 201, 120, 0.72);
  font-weight: 400;
}

.topbar__rule {
  width: 1px;
  height: 16px;
  background: var(--line);
}

.live {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--text-3);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.live__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--good);
  box-shadow: 0 0 0 0 rgba(78, 203, 146, 0.5);
  animation: live-pulse 2.8s ease-out infinite;
}

@keyframes live-pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(78, 203, 146, 0.45);
  }
  55% {
    box-shadow: 0 0 0 5px rgba(78, 203, 146, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(78, 203, 146, 0);
  }
}

.clock {
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.operator {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-left: 13px;
  border-left: 1px solid var(--line);
}

.operator__avatar {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  background: var(--panel-2);
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: 0.02em;
}

.operator__meta {
  display: flex;
  flex-direction: column;
  line-height: 1.25;
}

.operator__name {
  font-size: 11px;
  color: var(--text);
}

.operator__role {
  font-size: 9px;
  color: var(--text-3);
}

/* --------------------------------------------------------------------------
   Page frame
   -------------------------------------------------------------------------- */

.main {
  width: 100%;
  max-width: 1480px;
  margin: 0 auto;
  padding: 18px 20px 44px;
}

.pagehead {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 14px;
}

.eyebrow {
  margin-bottom: 3px;
  color: var(--text-3);
  font-size: 9.5px;
  font-weight: 500;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

h1 {
  font-size: 19px;
  font-weight: 600;
  letter-spacing: -0.015em;
  line-height: 1.2;
}

.pagehead__meta {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-bottom: 2px;
}

.sync {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-3);
  font-size: 10px;
  white-space: nowrap;
}

.sync__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--good);
  opacity: 0.85;
}

.icon-btn {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  padding: 0;
  color: var(--text-3);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 3px;
  cursor: pointer;
  transition: color 0.15s ease, border-color 0.15s ease, background-color 0.15s ease;
}

.icon-btn:hover {
  color: var(--text);
  background: var(--panel-2);
  border-color: var(--line-strong);
}

/* --------------------------------------------------------------------------
   Metrics
   -------------------------------------------------------------------------- */

.metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 12px;
}

.metric {
  padding: 12px 13px 10px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  min-width: 0;
}

.metric__top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.metric__label {
  overflow: hidden;
  color: var(--text-3);
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.trend {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  flex: none;
  padding: 2px 5px;
  border-radius: 3px;
  font-family: var(--mono);
  font-size: 9.5px;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.trend__arrow {
  font-size: 9px;
  line-height: 1;
}

.trend--good {
  color: var(--good);
  background: rgba(78, 203, 146, 0.09);
}

.trend--bad {
  color: var(--bad);
  background: rgba(242, 112, 102, 0.09);
}

.trend--flat {
  color: var(--text-2);
  background: rgba(255, 255, 255, 0.045);
}

.metric__value {
  margin-top: 2px;
  color: var(--text);
  font-size: 25px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.025em;
  line-height: 1.2;
  white-space: nowrap;
}

.metric__foot {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 8px;
  margin-top: 3px;
}

.metric__note {
  color: var(--text-3);
  font-size: 9.5px;
  white-space: nowrap;
}

.spark {
  flex: none;
  width: 72px;
  height: 21px;
  overflow: visible;
}

.spark__line {
  fill: none;
  stroke-width: 1.4;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}

.spark--good .spark__line {
  stroke: var(--good);
  opacity: 0.75;
}

.spark--bad .spark__line {
  stroke: var(--bad);
  opacity: 0.75;
}

.spark--flat .spark__line {
  stroke: var(--accent);
  opacity: 0.6;
}

.spark__dot {
  fill: currentColor;
}

/* --------------------------------------------------------------------------
   Panels
   -------------------------------------------------------------------------- */

.panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.panel__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 16px 11px;
  border-bottom: 1px solid var(--line-2);
}

.panel__title {
  min-width: 0;
}

.panel__title h2 {
  font-size: 13px;
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.3;
}

.panel__sub {
  margin-top: 2px;
  color: var(--text-3);
  font-size: 10.5px;
  line-height: 1.35;
}

.panel__hint {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--text-3);
  font-size: 9.5px;
  white-space: nowrap;
}

kbd {
  min-width: 16px;
  padding: 1px 4px;
  background: var(--panel-2);
  border: 1px solid var(--line);
  border-radius: 2px;
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 9px;
  text-align: center;
}

/* --------------------------------------------------------------------------
   Throughput chart
   -------------------------------------------------------------------------- */

.chart-panel {
  margin-bottom: 12px;
}

.chart__head {
  align-items: center;
}

.chart-readout {
  display: flex;
  align-items: baseline;
  gap: 7px;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.chart-readout__label {
  color: var(--text-3);
  font-size: 8.5px;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.chart-readout__value {
  color: var(--text);
  font-size: 14px;
  line-height: 1;
}

.chart-readout__value small {
  margin-left: 3px;
  color: var(--text-3);
  font-size: 9px;
  font-family: var(--font);
  letter-spacing: 0.01em;
}

.chart-readout__when {
  color: var(--text-3);
  font-size: 10px;
}

.chart-figure {
  padding: 12px 16px 8px;
}

.chart {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  grid-template-rows: 176px 20px;
  column-gap: 9px;
}

.chart__y {
  position: relative;
  grid-column: 1;
  grid-row: 1;
  margin: 5px 0;
  font-family: var(--mono);
  font-size: 8.5px;
  color: var(--text-3);
}

.chart__y span {
  position: absolute;
  right: 0;
  top: calc(var(--t) * 1%);
  transform: translateY(-50%);
  line-height: 1;
}

.chart__plot {
  position: relative;
  grid-column: 2;
  grid-row: 1;
  margin: 5px 0;
}

.chart__grid {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.chart__grid span {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(var(--t) * 1%);
  border-top: 1px solid var(--line-2);
}

.chart__grid span:first-child {
  border-top-color: #26303c;
}

.bars {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(24, minmax(0, 1fr));
  gap: 3px;
  align-items: end;
  height: 100%;
}

.bar {
  position: relative;
  display: flex;
  align-items: flex-end;
  height: 100%;
}

.bar::before {
  content: "";
  position: absolute;
  inset: -2px -1px 0;
  background: rgba(255, 255, 255, 0.035);
  opacity: 0;
  transition: opacity 0.12s ease;
}

.bar:hover::before {
  opacity: 1;
}

.bar__fill {
  position: relative;
  width: 100%;
  height: calc(var(--h) * 1%);
  background: #2d3b4d;
  border-radius: 1px 1px 0 0;
  transform: scaleY(0);
  transform-origin: bottom;
  transition: transform 0.55s cubic-bezier(0.2, 0.7, 0.2, 1) var(--d, 0ms),
    background-color 0.12s ease;
  will-change: transform;
}

.bars.is-ready .bar__fill {
  transform: scaleY(1);
}

.bar:hover .bar__fill {
  background: #8cb8ff;
}

.bar--peak .bar__fill {
  background: var(--accent);
}

.bar--peak:hover .bar__fill {
  background: #a3c8ff;
}

.chart__x {
  grid-column: 2;
  grid-row: 2;
  display: grid;
  grid-template-columns: repeat(24, minmax(0, 1fr));
  padding-top: 5px;
  font-family: var(--mono);
  font-size: 8.5px;
  color: var(--text-3);
}

.chart__x span {
  grid-column: span 4;
  white-space: nowrap;
}

.chart-table table {
  border-collapse: collapse;
}

/* --------------------------------------------------------------------------
   Incidents: layout, filters, table
   -------------------------------------------------------------------------- */

.incident-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 342px;
  gap: 12px;
  align-items: start;
}

.table-panel {
  min-width: 0;
  overflow: hidden;
}

.filters {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--line-2);
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  min-width: 0;
}

.chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 26px;
  padding: 0 8px;
  color: var(--text-3);
  background: transparent;
  border: 1px solid var(--line);
  border-radius: 3px;
  font-size: 10.5px;
  line-height: 1;
  cursor: pointer;
  transition: color 0.13s ease, background-color 0.13s ease, border-color 0.13s ease;
}

.chip:hover {
  color: var(--text-2);
  background: var(--panel-2);
}

.chip[aria-pressed="true"] {
  color: var(--text);
  background: var(--panel-3);
  border-color: var(--line-strong);
}

.chip__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
}

.chip__n {
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 9px;
  font-variant-numeric: tabular-nums;
}

.chip[aria-pressed="true"] .chip__n {
  color: var(--text-2);
}

.chip[data-severity="critical"] .chip__dot {
  background: var(--crit);
}

.chip[data-severity="high"] .chip__dot {
  background: var(--high);
}

.chip[data-severity="medium"] .chip__dot {
  background: var(--medium);
}

.chip[data-severity="low"] .chip__dot {
  background: var(--low);
}

.tools {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.search {
  position: relative;
  display: flex;
  align-items: center;
}

.search__icon {
  position: absolute;
  left: 8px;
  color: var(--text-3);
  pointer-events: none;
}

.search input {
  width: 158px;
  height: 28px;
  padding: 0 8px 0 26px;
  color: var(--text);
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: 3px;
  font-size: 11px;
  transition: border-color 0.13s ease;
}

.search input::placeholder {
  color: var(--text-3);
}

.search input:hover {
  border-color: var(--line-strong);
}

.search input:focus {
  border-color: var(--accent-line);
}

.search input:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.search input::-webkit-search-cancel-button {
  -webkit-appearance: none;
  appearance: none;
}

.select {
  position: relative;
}

.select select {
  height: 28px;
  max-width: 138px;
  padding: 0 24px 0 8px;
  color: var(--text-2);
  background-color: var(--bg-2);
  background-image: url("data:image/svg+xml;charset=UTF-8,%3Csvg xmlns='http://www.w3.org/2000/svg' width='9' height='6' fill='none' stroke='%2376828f' stroke-width='1.4' stroke-linecap='round'%3E%3Cpath d='m1 1.2 3.5 3.5L8 1.2'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: right 8px center;
  border: 1px solid var(--line);
  border-radius: 3px;
  font-size: 11px;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  text-overflow: ellipsis;
  transition: border-color 0.13s ease, color 0.13s ease;
}

.select select:hover {
  color: var(--text);
  border-color: var(--line-strong);
}

.select select:focus {
  border-color: var(--accent-line);
}

.select select option {
  background: var(--panel-2);
  color: var(--text);
}

.select--sort {
  display: none;
}

.btn-quiet {
  height: 28px;
  padding: 0 7px;
  color: var(--text-3);
  background: transparent;
  border: 1px solid transparent;
  border-radius: 3px;
  font-size: 10.5px;
  cursor: pointer;
  transition: color 0.13s ease, background-color 0.13s ease;
}

.btn-quiet:hover:not(:disabled) {
  color: var(--text);
  background: var(--panel-2);
}

.btn-quiet:disabled {
  opacity: 0.35;
  cursor: default;
}

.table-wrap {
  position: relative;
}

.incident-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.col-sev {
  width: 94px;
}

.col-service {
  width: 126px;
}

.col-age {
  width: 74px;
  text-align: right;
}

.col-owner {
  width: 112px;
}

.col-status {
  width: 116px;
}

.col-open {
  width: 26px;
}

.incident-table th {
  padding: 0;
  color: var(--text-3);
  background: #10151c;
  border-bottom: 1px solid var(--line-2);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.09em;
  text-align: left;
  text-transform: uppercase;
  white-space: nowrap;
}

.incident-table th > span,
.col-incident {
  display: block;
  padding: 8px 10px;
}

.incident-table th.col-open {
  padding: 8px 10px;
}

.th-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  width: 100%;
  padding: 8px 10px;
  color: inherit;
  background: transparent;
  border: 0;
  font: inherit;
  letter-spacing: inherit;
  text-align: inherit;
  text-transform: inherit;
  cursor: pointer;
}

.th-btn:hover {
  color: var(--text-2);
}

.col-age .th-btn {
  justify-content: flex-end;
}

.th-btn__mark {
  display: inline-block;
  width: 7px;
  color: var(--accent);
  font-size: 9px;
  line-height: 1;
}

.incident-table th[aria-sort="ascending"] .th-btn__mark::before {
  content: "↑";
}

.incident-table th[aria-sort="descending"] .th-btn__mark::before {
  content: "↓";
}

.incident-table th[aria-sort="ascending"],
.incident-table th[aria-sort="descending"] {
  color: var(--text-2);
}

.incident-table tbody tr {
  position: relative;
  cursor: pointer;
  transition: background-color 0.12s ease;
}

.incident-table tbody tr:hover {
  background: #161c24;
}

.incident-table tbody tr.is-selected {
  background: var(--accent-soft);
}

.incident-table tbody tr.is-selected td:first-child {
  box-shadow: inset 2px 0 0 var(--accent);
}

.incident-table td {
  height: 45px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--line-2);
  color: var(--text-2);
  font-size: 11.5px;
  vertical-align: middle;
}

.incident-table tbody tr:last-child td {
  border-bottom: 0;
}

.sev {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.05em;
  line-height: 1;
  text-transform: uppercase;
  white-space: nowrap;
}

.sev__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 0 3px rgba(var(--sev-rgb), 0.1);
}

.sev--critical {
  color: var(--crit);
  --sev-rgb: 255, 107, 98;
}

.sev--high {
  color: var(--high);
  --sev-rgb: 247, 164, 90;
}

.sev--medium {
  color: var(--medium);
  --sev-rgb: 227, 198, 90;
}

.sev--low {
  color: var(--low);
  --sev-rgb: 147, 160, 178;
}

.incident-id {
  display: block;
  margin-bottom: 1px;
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 8.5px;
  letter-spacing: 0.04em;
  line-height: 1.2;
}

.rowbtn {
  display: block;
  width: 100%;
  overflow: hidden;
  padding: 0;
  color: var(--text);
  background: transparent;
  border: 0;
  font-size: 11.5px;
  font-weight: 500;
  line-height: 1.3;
  text-align: left;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
}

.rowbtn:hover {
  color: #cfe1ff;
}

.rowbtn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 2px;
}

.service {
  display: block;
  overflow: hidden;
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: -0.01em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cell-age {
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 10px;
  font-variant-numeric: tabular-nums;
  text-align: right;
  white-space: nowrap;
}

.cell-owner {
  overflow: hidden;
  color: var(--text-2);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cell-owner.is-unassigned {
  color: var(--text-3);
  font-style: italic;
}

.status {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--text-2);
  font-size: 10px;
  white-space: nowrap;
}

.status__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--text-3);
}

.status--open .status__dot {
  background: #8794a6;
}

.status--investigating .status__dot {
  background: var(--accent);
  box-shadow: 0 0 0 3px rgba(111, 168, 255, 0.1);
}

.status--monitoring .status__dot {
  background: var(--warn);
}

.status--acknowledged .status__dot {
  background: var(--good);
}

.cell-open {
  color: var(--text-3);
  text-align: right;
}

.cell-open svg {
  margin-left: auto;
  opacity: 0;
  transition: opacity 0.12s ease, transform 0.12s ease;
}

tr:hover .cell-open svg,
tr.is-selected .cell-open svg {
  opacity: 1;
}

/* Mobile incident cards (desktop hidden) */

.card-list {
  display: none;
}

.empty {
  padding: 44px 20px 48px;
  text-align: center;
}

.empty svg {
  margin: 0 auto 10px;
  color: var(--text-3);
}

.empty h3 {
  font-size: 13px;
  font-weight: 600;
}

.empty p {
  max-width: 320px;
  margin: 4px auto 14px;
  color: var(--text-3);
  font-size: 11px;
  line-height: 1.5;
}

/* --------------------------------------------------------------------------
   Detail panel
   -------------------------------------------------------------------------- */

.detail {
  position: sticky;
  top: calc(var(--topbar-h) + 12px);
  display: flex;
  flex-direction: column;
  max-height: calc(100vh - var(--topbar-h) - 24px);
  overflow: auto;
  scrollbar-width: thin;
  scrollbar-color: #2a3442 transparent;
}

.detail::-webkit-scrollbar {
  width: 8px;
}

.detail::-webkit-scrollbar-thumb {
  background: #2a3442;
  border-radius: 4px;
}

.detail__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 12px 10px 14px;
  border-bottom: 1px solid var(--line-2);
}

.detail__ident {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  flex-wrap: wrap;
}

.detail__id {
  color: var(--text-2);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: 0.05em;
}

.detail__close {
  width: 24px;
  height: 24px;
  flex: none;
}

.detail__body {
  padding: 13px 14px 14px;
}

.detail__title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.012em;
  line-height: 1.3;
}

.detail__title:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 2px;
}

.detail__service {
  margin-top: 3px;
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 9.5px;
  letter-spacing: 0.01em;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.detail__actions {
  margin-top: 11px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid transparent;
  border-radius: 3px;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition: background-color 0.13s ease, border-color 0.13s ease,
    color 0.13s ease;
}

.btn--primary {
  width: 100%;
  color: #07101f;
  background: var(--accent);
  border-color: var(--accent);
}

.btn--primary:hover {
  background: #8bbaff;
  border-color: #8bbaff;
}

.btn--primary:active {
  background: #5c98f2;
}

.btn--ack.is-done {
  color: var(--good);
  background: rgba(78, 203, 146, 0.1);
  border-color: rgba(78, 203, 146, 0.28);
  cursor: default;
}

.btn--ack.is-done:hover {
  background: rgba(78, 203, 146, 0.12);
  border-color: rgba(78, 203, 146, 0.34);
}

.btn--soft {
  height: 29px;
  color: var(--text-2);
  background: var(--panel-2);
  border-color: var(--line);
  font-weight: 500;
}

.btn--soft:hover {
  color: var(--text);
  border-color: var(--line-strong);
}

.meta {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px 12px;
  margin-top: 13px;
  padding-top: 12px;
  border-top: 1px solid var(--line-2);
}

.meta dt {
  color: var(--text-3);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.meta dd {
  margin-top: 1px;
  color: var(--text-2);
  font-size: 10.5px;
  overflow-wrap: anywhere;
}

.meta dd.mono {
  font-family: var(--mono);
  font-size: 10px;
  font-variant-numeric: tabular-nums;
}

.detail__summary {
  margin-top: 12px;
  color: var(--text-2);
  font-size: 11px;
  line-height: 1.55;
}

.detail__section {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--line-2);
}

.detail__section h3 {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
  color: var(--text-3);
  font-size: 8.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.detail__section h3 span {
  color: var(--text-3);
  font-family: var(--mono);
  font-weight: 400;
  letter-spacing: 0;
}

.signals {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}

.signal {
  padding: 7px 8px 6px;
  background: var(--bg-2);
  border: 1px solid var(--line-2);
  border-radius: 3px;
  min-width: 0;
}

.signal__value {
  display: block;
  color: var(--text);
  font-family: var(--mono);
  font-size: 11.5px;
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
  white-space: nowrap;
}

.signal__label {
  display: block;
  margin-top: 2px;
  overflow: hidden;
  color: var(--text-3);
  font-size: 7.5px;
  letter-spacing: 0.08em;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  position: absolute;
  left: 3px;
  top: 5px;
  bottom: 6px;
  width: 1px;
  background: var(--line);
}

.timeline li {
  position: relative;
  padding-left: 14px;
  margin-bottom: 9px;
}

.timeline li:last-child {
  margin-bottom: 0;
}

.timeline li::before {
  content: "";
  position: absolute;
  left: 1px;
  top: 4px;
  width: 5px;
  height: 5px;
  background: #3a4657;
  border-radius: 50%;
  box-shadow: 0 0 0 2px var(--panel);
}

.timeline li:first-child::before {
  background: var(--accent);
}

.timeline time {
  display: block;
  color: var(--text-3);
  font-family: var(--mono);
  font-size: 8.5px;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.03em;
  line-height: 1.3;
}

.timeline__text {
  color: var(--text-2);
  font-size: 10.5px;
  line-height: 1.45;
}

.timeline__text b {
  color: var(--text);
  font-weight: 500;
}

.note {
  display: flex;
  align-items: center;
  gap: 2px;
  margin-top: 12px;
  padding: 2px;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: 3px;
  transition: border-color 0.13s ease;
}

.note:focus-within {
  border-color: var(--accent-line);
}

.note input {
  flex: 1;
  min-width: 0;
  height: 26px;
  padding: 0 7px;
  color: var(--text);
  background: transparent;
  border: 0;
  font-size: 10.5px;
  outline: none;
}

.note input::placeholder {
  color: var(--text-3);
}

.note button {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  flex: none;
  color: var(--text-3);
  background: transparent;
  border: 0;
  border-radius: 2px;
  cursor: pointer;
}

.note button:hover {
  color: var(--text);
  background: var(--panel-3);
}

.detail-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 300px;
  padding: 36px 24px;
  text-align: center;
}

.detail-empty svg {
  color: var(--text-3);
  margin-bottom: 10px;
}

.detail-empty h2 {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-2);
}

.detail-empty p {
  max-width: 230px;
  margin-top: 4px;
  color: var(--text-3);
  font-size: 10.5px;
  line-height: 1.5;
}

/* --------------------------------------------------------------------------
   Toast
   -------------------------------------------------------------------------- */

.toast {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 80;
  max-width: 340px;
  padding: 10px 13px;
  background: #18202a;
  border: 1px solid #2c3746;
  border-left: 2px solid var(--accent);
  border-radius: 3px;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.38);
  color: var(--text);
  font-size: 11.5px;
  line-height: 1.4;
  opacity: 0;
  pointer-events: none;
  transform: translateY(8px);
  transition: opacity 0.16s ease, transform 0.16s ease;
}

.toast.is-visible {
  opacity: 1;
  transform: translateY(0);
}

.toast b {
  font-weight: 600;
}

.toast span {
  color: var(--text-2);
}

/* --------------------------------------------------------------------------
   Responsive
   -------------------------------------------------------------------------- */

@media (max-width: 1240px) {
  .incident-layout {
    grid-template-columns: minmax(0, 1fr) 322px;
  }

  .search input {
    width: 138px;
  }

  .select select {
    max-width: 124px;
  }
}

@media (max-width: 1120px) {
  .incident-layout {
    grid-template-columns: minmax(0, 1fr);
  }

  .detail {
    position: static;
    max-height: none;
  }

  .detail__body {
    padding-bottom: 16px;
  }

  .signals {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  .metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }

  .metric__value {
    font-size: 23px;
  }

  .chart {
    grid-template-rows: 162px 20px;
  }

  .search input {
    width: 100%;
  }

  .tools {
    flex: 1;
    justify-content: flex-end;
  }

  .search {
    flex: 1;
    max-width: 240px;
  }
}

@media (max-width: 760px) {
  .app {
    display: block;
  }

  .rail {
    position: fixed;
    top: auto;
    right: 0;
    bottom: 0;
    left: 0;
    flex-direction: row;
    align-items: stretch;
    width: auto;
    height: 58px;
    padding: 0 6px;
    background: #0a0d11;
    border-top: 1px solid var(--line);
    border-right: 0;
  }

  .rail__brand,
  .rail__foot {
    display: none;
  }

  .rail__nav {
    flex-direction: row;
    align-items: stretch;
    justify-content: space-between;
    gap: 0;
    height: 100%;
    flex: 1;
  }

  .rail__nav li {
    flex: 1;
    width: auto;
  }

  .rail__item {
    width: 100%;
    height: 100%;
    margin: 0;
    gap: 3px;
    border-radius: 0;
    font-size: 8.5px;
  }

  .rail__item:hover {
    background: transparent;
  }

  .rail__item[aria-current="page"] {
    background: transparent;
    color: var(--accent);
  }

  .rail__item[aria-current="page"]::before {
    left: 50%;
    top: 0;
    bottom: auto;
    width: 22px;
    height: 2px;
    transform: translateX(-50%);
  }

  .rail__badge {
    display: none;
  }

  .workspace {
    padding-bottom: 58px;
  }

  .topbar {
    height: 50px;
    gap: 10px;
    padding: 0 14px;
  }

  .wordmark {
    display: inline;
  }

  .context,
  .topbar__rule,
  .clock,
  .operator__meta {
    display: none;
  }

  .topbar__right {
    gap: 10px;
  }

  .status-pill {
    height: 22px;
    padding: 0 7px;
    font-size: 10px;
  }

  .status-pill__detail {
    display: none;
  }

  .operator {
    padding-left: 10px;
  }

  .live {
    font-size: 9px;
    letter-spacing: 0.06em;
  }

  .main {
    padding: 13px 14px 30px;
  }

  .pagehead {
    align-items: flex-start;
    margin-bottom: 11px;
  }

  h1 {
    font-size: 18px;
  }

  .sync {
    display: none;
  }

  .pagehead__meta {
    padding-top: 6px;
  }

  .metrics {
    gap: 8px;
    margin-bottom: 10px;
  }

  .metric {
    padding: 10px 11px 9px;
  }

  .metric__label {
    font-size: 8.5px;
    letter-spacing: 0.06em;
  }

  .trend {
    font-size: 9px;
    padding: 2px 4px;
  }

  .metric__value {
    margin-top: 3px;
    font-size: 21px;
  }

  .metric__note {
    font-size: 8.5px;
  }

  .spark {
    width: 54px;
    height: 18px;
  }

  .panel__head {
    padding: 11px 12px 10px;
  }

  .panel__hint {
    display: none;
  }

  .chart-figure {
    padding: 10px 12px 6px;
  }

  .chart {
    grid-template-columns: 24px minmax(0, 1fr);
    grid-template-rows: 142px 20px;
    column-gap: 6px;
  }

  .chart__y,
  .chart__x {
    font-size: 7.5px;
  }

  .chart__x span:nth-child(even) {
    visibility: hidden;
  }

  .bars {
    gap: 2px;
  }

  .chart-readout {
    gap: 5px;
  }

  .chart-readout__value {
    font-size: 12.5px;
  }

  .chart-readout__when {
    display: none;
  }

  .chart-panel {
    margin-bottom: 10px;
  }

  .incident-layout {
    gap: 10px;
  }

  .filters {
    flex-direction: column;
    align-items: stretch;
    gap: 8px;
    padding: 9px 12px;
  }

  .chips {
    gap: 4px;
  }

  .chip {
    height: 25px;
    padding: 0 7px;
    font-size: 10px;
  }

  .tools {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 6px;
  }

  .search {
    grid-column: 1 / -1;
    max-width: none;
  }

  .search input {
    width: 100%;
    height: 30px;
  }

  .select select {
    width: 100%;
    max-width: none;
    height: 30px;
  }

  .select--sort {
    display: block;
  }

  .btn-quiet {
    grid-column: 1 / -1;
    justify-self: start;
    height: 22px;
    padding: 0;
  }

  .incident-table {
    display: none;
  }

