  /* ------------------------------------------------------------------------
     Metrics
     ------------------------------------------------------------------------ */

  function sparkline(values, tone) {
    const width = 72;
    const height = 21;
    const padY = 2.5;
    const min = Math.min(...values);
    const max = Math.max(...values);
    const range = max - min || 1;
    const step = (width - 4) / (values.length - 1);

    const points = values.map((value, index) => {
      const x = 2 + index * step;
      const y = height - padY - ((value - min) / range) * (height - padY * 2);
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    });

    const lastPoint = points[points.length - 1].split(",");

    return `<svg class="spark spark--${tone}" viewBox="0 0 ${width} ${height}" aria-hidden="true" focusable="false">
      <polyline class="spark__line" points="${points.join(" ")}"></polyline>
      <circle class="spark__dot" cx="${lastPoint[0]}" cy="${lastPoint[1]}" r="1.7"></circle>
    </svg>`;
  }

  function renderMetrics() {
    metricsEl.innerHTML = METRICS.map((metric) => {
