        </article>`;
    }).join("");
  }

  /* ------------------------------------------------------------------------
     Throughput chart
     ------------------------------------------------------------------------ */

  function renderChart() {
    const values = THROUGHPUT;
    const peakValue = Math.max(...values);
    const peakIndex = values.indexOf(peakValue);
    const mean = Math.round(values.reduce((sum, value) => sum + value, 0) / values.length);
    const minValue = Math.min(...values);

    barsEl.innerHTML = values
      .map((value, index) => {
        const hour = `${pad(index)}:00`;
        return `<span class="bar${value === peakValue ? " bar--peak" : ""}"
          data-hour="${hour}" data-value="${value}"
          style="--h:${value};--d:${index * 12}ms" aria-hidden="true">
          <span class="bar__fill"></span>
        </span>`;
      })
      .join("");

    chartXEl.innerHTML = [0, 4, 8, 12, 16, 20]
      .map((hour) => `<span>${pad(hour)}:00</span>`)
      .join("");

    chartEl.setAttribute(
      "aria-label",
      `Throughput over the last 24 hours. ${minValue} to ${peakValue} events per minute; peak ${peakValue} at ${pad(
        peakIndex
      )}:00; mean ${mean}.`
    );

    chartTableEl.innerHTML = `
      <table>
        <caption>Hourly throughput in events per minute</caption>
        <thead><tr><th scope="col">Hour (UTC)</th><th scope="col">Events per minute</th></tr></thead>
        <tbody>
          ${values
            .map(
              (value, index) =>
                `<tr><th scope="row">${pad(index)}:00</th><td>${value}</td></tr>`
            )
            .join("")}
        </tbody>
      </table>`;

    setReadout("Peak", peakValue, `${pad(peakIndex)}:00`);

    barsEl.classList.remove("is-ready");
    requestAnimationFrame(() => {
      requestAnimationFrame(() => barsEl.classList.add("is-ready"));
    });
  }

  function setReadout(label, value, when) {
    chartReadoutEl.innerHTML = `
      <span class="chart-readout__label">${label}</span>
      <span class="chart-readout__value">${value}<small>evt/min</small></span>
      <span class="chart-readout__when">${when}</span>`;
  }

  function bindChartHover() {
    barsEl.addEventListener("pointerover", (event) => {
      const bar = event.target.closest(".bar");
      if (!bar) return;
      setReadout("Hour", bar.dataset.value, bar.dataset.hour);
    });

    barsEl.addEventListener("pointerleave", () => {
      const peakValue = Math.max(...THROUGHPUT);
      setReadout("Peak", peakValue, `${pad(THROUGHPUT.indexOf(peakValue))}:00`);
    });
  }

  /* ------------------------------------------------------------------------
     Filtering and sorting
     ------------------------------------------------------------------------ */

  function visibleIncidents() {
    const { severity, service, status, q } = state.filters;
    const query = q.trim().toLowerCase();

    const rows = state.incidents.filter((incident) => {
      if (severity !== "all" && incident.severity !== severity) return false;
      if (service !== "all" && incident.service !== service) return false;
      if (status !== "all" && incident.status !== status) return false;
      if (!query) return true;
      const haystack =
        `${incident.id} ${incident.title} ${incident.service} ${incident.owner}`.toLowerCase();
      return haystack.includes(query);
    });

    return rows.sort(compareIncidents);
  }

  function compareIncidents(a, b) {
    const { key, dir } = state.sort;
    const direction = dir === "asc" ? 1 : -1;
    const severityTie = () => SEVERITY_RANK[a.severity] - SEVERITY_RANK[b.severity];
    const ageTie = () => a.ageMinutes - b.ageMinutes;

    if (key === "severity") {
      return severityTie() * direction || ageTie() || a.id.localeCompare(b.id);
    }

    if (key === "age") {
      return ageTie() * direction || severityTie() || a.id.localeCompare(b.id);
    }

    let valueA = "";
    let valueB = "";
    if (key === "service") {
      valueA = a.service;
      valueB = b.service;
    } else if (key === "owner") {
      valueA = a.owner;
      valueB = b.owner;
    } else if (key === "status") {
      valueA = STATUS_LABEL[a.status];
      valueB = STATUS_LABEL[b.status];
    } else {
      valueA = a.id;
      valueB = b.id;
    }

    return (
      valueA.localeCompare(valueB) * direction || severityTie() || ageTie() || a.id.localeCompare(b.id)
    );
  }

  /* ------------------------------------------------------------------------
     Rendering: filters, table, cards, detail
     ------------------------------------------------------------------------ */

  function renderChips() {
    const counts = state.incidents.reduce(
      (acc, incident) => {
        acc[incident.severity] += 1;
        return acc;
      },
      { critical: 0, high: 0, medium: 0, low: 0 }
    );

    const options = [{ key: "all", label: "All", count: state.incidents.length }].concat(
      SEVERITIES.map((severity) => ({
        key: severity,
        label: SEVERITY_LABEL[severity],
        count: counts[severity],
      }))
    );

    chipsEl.innerHTML = options
      .map((option) => {
        const active = state.filters.severity === option.key;
        const dot =
          option.key === "all"
            ? ""
            : `<span class="chip__dot" aria-hidden="true"></span>`;
        return `<button class="chip" type="button" data-severity="${option.key}" aria-pressed="${active}">
          ${dot}${option.label}<span class="chip__n">${option.count}</span>
        </button>`;
      })
      .join("");
  }

