  function buildTimeline(incident) {
    const opened = incident.openedAt;
    const span = incident.ageMinutes;
    const events = [
      {
        at: opened,
        text: `Alert opened on <b>${incident.service}</b> — ${incident.title.toLowerCase()}.`,
      },
      {
        at: opened + Math.min(2, span * 0.15) * 60_000,
        text: `Routed to <b>#${incident.service}-oncall</b> under the P2 escalation policy.`,
      },
    ];

    if (incident.owner !== "Unassigned") {
      events.push({
        at: opened + Math.min(5, span * 0.3) * 60_000,
        text: `<b>${incident.owner}</b> claimed ownership.`,
      });
    }

    if (["investigating", "monitoring", "acknowledged"].includes(incident.status)) {
      events.push({
        at: opened + span * 0.45 * 60_000,
        text: incident.timelineNote,
      });
    }

    if (incident.status === "monitoring") {
      events.push({
        at: opened + span * 0.8 * 60_000,
        text: "Mitigation applied; error budget under observation before resolving.",
      });
    }

    if (
      incident.status === "acknowledged" &&
      !incident.events.some((event) => event.kind === "ack")
    ) {
      events.push({
        at: opened + span * 0.55 * 60_000,
        text: `<b>${incident.owner}</b> acknowledged the page; remediation continues.`,
      });
    }

    incident.events.forEach((event) => events.push(event));

    return events.sort((a, b) => b.at - a.at).slice(0, 8);
  }

