            <button type="submit" aria-label="Post note">
              <svg viewBox="0 0 20 20" width="14" height="14" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
                <path d="M3.5 10h12M11 5.5l4.5 4.5L11 14.5"></path>
              </svg>
            </button>
          </form>
        </section>
      </div>`;
  }

  function renderSummary(rows) {
    const total = state.incidents.length;
    const critical = state.incidents.filter((incident) => incident.severity === "critical").length;

    if (hasActiveFilters() || rows.length !== total) {
      pageCountEl.textContent = `${rows.length} of ${total} incidents`;
    } else {
      pageCountEl.textContent = `${total} active · ${critical} critical`;
    }

    navCount.textContent = total;

    window.clearTimeout(resultsTimer);
    resultsTimer = window.setTimeout(() => {
      resultsLive.textContent = `${rows.length} of ${total} incidents shown.`;
    }, 350);
  }

  function updateClearState() {
    clearBtn.disabled = !hasActiveFilters();
  }

  function syncControls() {
    if (serviceSelect.value !== state.filters.service) serviceSelect.value = state.filters.service;
    if (statusSelect.value !== state.filters.status) statusSelect.value = state.filters.status;
    if (searchEl.value !== state.filters.q) searchEl.value = state.filters.q;
  }

  function updateAriaSort() {
    $$(".incident-table th[data-sortable], .incident-table th[aria-sort]").forEach((th) => {
      const button = th.querySelector("[data-sort]");
      if (!button) return;
      if (button.dataset.sort === state.sort.key) {
        th.setAttribute("aria-sort", state.sort.dir === "asc" ? "ascending" : "descending");
      } else {
        th.setAttribute("aria-sort", "none");
      }
    });
  }

  function refreshList({ ensureSelection = false } = {}) {
    const rows = visibleIncidents();

    if (ensureSelection && !rows.some((incident) => incident.id === state.selectedId)) {
      state.selectedId = rows.length ? rows[0].id : null;
    }

    renderChips();
    renderTable(rows);
    renderCards(rows);
    renderDetail();
    renderSummary(rows);
    updateClearState();
    syncControls();

    tableEl.hidden = rows.length === 0;
    cardsEl.hidden = rows.length === 0;
    emptyEl.hidden = rows.length !== 0;
  }

  /* ------------------------------------------------------------------------
     Selection and incident actions
     ------------------------------------------------------------------------ */

  function selectIncident(id) {
    if (!getIncident(id)) return;

    state.selectedId = id;
    const rows = visibleIncidents();
    renderChips();
    renderTable(rows);
    renderCards(rows);
    renderDetail();

    if (NARROW.matches) {
      const title = $("#detail-title", detailEl);
      title?.focus({ preventScroll: true });
      detailEl.scrollIntoView({
        behavior: REDUCED_MOTION.matches ? "auto" : "smooth",
        block: "start",
      });
    } else {
      visibleOpenControl(id)?.focus({ preventScroll: true });
    }

    const incident = getIncident(id);
    announce(`Detail panel opened for ${id}, ${incident.title}, ${SEVERITY_LABEL[incident.severity]} severity.`);
  }

  function acknowledgeSelected() {
    const incident = getSelected();
    if (!incident || incident.status === "acknowledged") return;

    incident.status = "acknowledged";
    if (incident.owner === "Unassigned") incident.owner = OPERATOR;
    incident.events.push({
      at: Date.now(),
      kind: "ack",
      text: `<b>${OPERATOR}</b> acknowledged the page. Incident stays open for triage.`,
    });

    refreshList();
    $("#detail [data-action='ack']")?.focus({ preventScroll: true });

    showToast(
      `<b>${incident.id}</b> <span>acknowledged · owner ${incident.owner}</span>`
    );
  }

  function addNote(form) {
    const incident = getSelected();
    const input = form.querySelector("input[name='note']");
    if (!incident || !input) return;

    const value = input.value.trim();
    if (!value) return;

    incident.events.push({
      at: Date.now(),
      kind: "note",
      text: `<b>${OPERATOR}</b> noted: “${escapeHTML(value)}”`,
    });

    renderDetail();
    $("#detail [name='note']")?.focus({ preventScroll: true });
    announce(`Note added to ${incident.id}.`);
  }

  function closeDetail() {
    const previous = state.selectedId;
    state.selectedId = null;

    const rows = visibleIncidents();
    renderChips();
    renderTable(rows);
    renderCards(rows);
    renderDetail();

    if (previous) visibleOpenControl(previous)?.focus({ preventScroll: true });
    announce("Incident details closed.");
  }

  function clearFilters() {
    state.filters = { severity: "all", service: "all", status: "all", q: "" };
    refreshList({ ensureSelection: true });
    announce("Filters cleared.");
  }

  /* ------------------------------------------------------------------------
     Event wiring
     ------------------------------------------------------------------------ */

  function bindEvents() {
    chipsEl.addEventListener("click", (event) => {
      const chip = event.target.closest("[data-severity]");
      if (!chip) return;
      state.filters.severity = chip.dataset.severity;
      refreshList({ ensureSelection: true });
      $(`[data-severity="${state.filters.severity}"]`, chipsEl)?.focus();
    });

    searchEl.addEventListener("input", () => {
      state.filters.q = searchEl.value;
      refreshList({ ensureSelection: true });
    });

    serviceSelect.addEventListener("change", () => {
      state.filters.service = serviceSelect.value;
      refreshList({ ensureSelection: true });
    });

    statusSelect.addEventListener("change", () => {
      state.filters.status = statusSelect.value;
      refreshList({ ensureSelection: true });
    });

    sortSelect.addEventListener("change", () => {
      const value = sortSelect.value;
      if (value === "severity") state.sort = { key: "severity", dir: "asc" };
      else if (value === "age") state.sort = { key: "age", dir: "asc" };
      else if (value === "age-desc") state.sort = { key: "age", dir: "desc" };
      else if (value === "service") state.sort = { key: "service", dir: "asc" };
      else if (value === "owner") state.sort = { key: "owner", dir: "asc" };
      updateAriaSort();
      refreshList();
    });

    $$(".incident-table th [data-sort]").forEach((button) => {
      button.addEventListener("click", () => {
        const key = button.dataset.sort;
        if (state.sort.key === key) {
          state.sort.dir = state.sort.dir === "asc" ? "desc" : "asc";
        } else {
          state.sort = { key, dir: "asc" };
        }
        updateAriaSort();
        refreshList();
      });
    });

    clearBtn.addEventListener("click", clearFilters);
    $("#empty-clear").addEventListener("click", clearFilters);

    tbodyEl.addEventListener("click", (event) => {
      const trigger = event.target.closest("[data-open]");
      const row = event.target.closest("tr[data-id]");
      if (trigger) selectIncident(trigger.dataset.open);
      else if (row) selectIncident(row.dataset.id);
    });

    cardsEl.addEventListener("click", (event) => {
      const trigger = event.target.closest("[data-open]");
      const card = event.target.closest(".incident-card");
      if (trigger) selectIncident(trigger.dataset.open);
      else if (card) selectIncident(card.dataset.id);
    });

    detailEl.addEventListener("click", (event) => {
      const action = event.target.closest("[data-action]");
      if (!action) return;
      if (action.dataset.action === "ack") acknowledgeSelected();
      if (action.dataset.action === "close") closeDetail();
    });

    detailEl.addEventListener("submit", (event) => {
      const form = event.target.closest("[data-action='note']");
      if (!form) return;
      event.preventDefault();
      addNote(form);
    });

    $("#refresh").addEventListener("click", () => {
      renderMetrics();
      renderChart();
      syncText.textContent = "Synced just now";
      showToast("<b>Dashboard refreshed</b> <span>Local snapshot · no network</span>");
    });

    $$("[data-nav-only]").forEach((button) => {
      button.addEventListener("click", () => {
        showToast(
          `<b>${button.dataset.navOnly}</b> <span>is not included in this preview.</span>`
        );
      });
    });

    document.addEventListener("keydown", (event) => {
      const target = event.target;
      const typing =
        target instanceof HTMLElement &&
        (target.tagName === "INPUT" ||
          target.tagName === "SELECT" ||
          target.tagName === "TEXTAREA" ||
          target.isContentEditable);

      if (event.key === "/" && !typing) {
        event.preventDefault();
        searchEl.focus();
      }
    });

    document.addEventListener("click", (event) => {
      const link = event.target.closest('a[href^="#"]');
      if (!link) return;
      const target = document.querySelector(link.getAttribute("href"));
      if (target) {
        // Let the browser handle the hash; this only keeps focus in the page.
        window.setTimeout(() => {
          target.setAttribute("tabindex", "-1");
          target.focus({ preventScroll: true });
        }, 0);
      }
    });
  }

  /* ------------------------------------------------------------------------
     Chrome: clock, services, boot
     ------------------------------------------------------------------------ */

  function startClock() {
    const tick = () => {
      const now = new Date();
      clockEl.textContent = `${pad(now.getUTCHours())}:${pad(now.getUTCMinutes())}:${pad(
        now.getUTCSeconds()
      )} UTC`;
      clockEl.dateTime = now.toISOString();
    };
    tick();
    window.setInterval(tick, 1000);
  }

  function populateServices() {
    const services = Array.from(new Set(state.incidents.map((incident) => incident.service))).sort();
    services.forEach((service) => {
      const option = document.createElement("option");
      option.value = service;
      option.textContent = service;
      serviceSelect.append(option);
    });
  }

  function init() {
    populateServices();
    renderMetrics();
    renderChart();
    bindChartHover();
    bindEvents();
    updateAriaSort();
    refreshList();
    startClock();
  }

  init();
})();

